package wgmodern;
import java.util.*;import com.mojang.authlib.GameProfile;import net.minecraft.gametest.framework.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.Blocks;import net.minecraft.core.BlockPos;import net.minecraft.nbt.CompoundTag;import net.minecraftforge.gametest.*;import net.minecraftforge.common.util.FakePlayerFactory;import tc4revival.research.*;
@GameTestHolder("witchinggadgets") @PrefixGameTestTemplate(false)
public class CameraServerTests {
 @GameTest(template="empty") public static void cameraConsumesOnePlateAndPreservesScanIdentity(GameTestHelper h){var level=h.getLevel();var p=FakePlayerFactory.get(level,new GameProfile(UUID.fromString("c2825ea9-0429-4d89-8623-0451a372b75f"),"CameraTester"));p.getInventory().clearContent();p.getInventory().setItem(0,new ItemStack(ScanCamera.mirrorGlass(),3));var data=KnowledgeSavedData.get(level.getServer());data.update(p.getUUID(),n->0,k->{for(var a:tc4revival.aspect.TCAspects.catalog().all())k.discover(a);return true;});var pos=h.absolutePos(new BlockPos(2,2,2));level.setBlockAndUpdate(pos,Blocks.STONE.defaultBlockState());var scan=ScanTargetResolver.block(level,pos).orElseThrow();var selection=new ScanTargetSelector.Selection(scan,Blocks.STONE.getName(),net.minecraft.world.phys.Vec3.atLowerCornerOf(pos).add(0,.25,0),15);h.assertTrue(ScanCamera.take(p,selection),"Taking a valid photograph succeeds");h.assertTrue(p.getInventory().countItem(ScanCamera.mirrorGlass())==2&&p.getInventory().countItem(Content.PLATE.get())==1,"Exactly one mirror glass becomes one plate");var plate=p.getInventory().items.stream().filter(s->s.is(Content.PLATE.get())).findFirst().orElseThrow();var restored=ItemStack.of(plate.save(new CompoundTag()));h.assertTrue(PhotoData.resolve(PhotoData.of(restored),level).orElseThrow().identity().equals(scan.identity()),"Photo identity survives save and resolves via authoritative current aspects");p.getInventory().clearContent();h.assertTrue(!ScanCamera.take(p,selection)&&p.getInventory().countItem(Content.PLATE.get())==0,"Even creative photograph acquisition requires original mirror-glass input");pass(h);}
 @GameTest(template="empty") public static void photoDevelopingScalesCostAndCopiesData(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.fromString("9d87e462-cb38-44bb-ba74-bcdf955880dc"),"PhotoCraftTester"));var scan=ScanTargetResolver.inventory(new ItemStack(Items.STONE)).orElseThrow();var data=PhotoData.summary(scan,Items.STONE.getDescription());data.put("item",new ItemStack(Items.STONE).save(new CompoundTag()));var plate=PhotoData.create(false,data);var grid=new net.minecraft.world.inventory.TransientCraftingContainer(p.inventoryMenu,3,3);grid.setItem(0,plate);for(int i=1;i<=4;i++){grid.setItem(i,new ItemStack(Items.PAPER));grid.setItem(i+4,new ItemStack(Items.BLACK_DYE));}var recipe=(PhotoDevelopingRecipe)h.getLevel().getRecipeManager().byKey(new net.minecraft.resources.ResourceLocation("witchinggadgets","photo_developing")).orElseThrow();h.assertTrue(recipe.matches(grid,h.getLevel()),"One plate plus four paper and four black dye matches");var out=recipe.assemble(grid,h.getLevel().registryAccess());h.assertTrue(out.getCount()==4&&out.is(Content.PHOTO.get())&&PhotoData.of(out).equals(data),"Original four-copy output retains target data");h.assertTrue(recipe.visCost(grid).values().stream().allMatch(n->n==20),"Four papers cost twenty of each original primal");PhotoData.of(out).putString("changed","output");h.assertTrue(!PhotoData.of(plate).contains("changed"),"Output NBT is independent of plate");grid.setItem(8,ItemStack.EMPTY);h.assertTrue(!recipe.matches(grid,h.getLevel()),"Unequal paper/ink rejected");grid.setItem(8,new ItemStack(Items.BLACK_DYE));grid.setItem(0,new ItemStack(Content.PLATE.get()));h.assertTrue(!recipe.matches(grid,h.getLevel()),"Blank plate cannot manufacture scan data");pass(h);}
 @GameTest(template="empty") public static void developedPhotoLearnsOnceAndKeepsUnknownParents(GameTestHelper h){var level=h.getLevel();var p=FakePlayerFactory.get(level,new GameProfile(UUID.fromString("f4803b5e-345e-46d3-a3a6-0e02d6e9e5d5"),"PhotoLearnTester"));var store=KnowledgeSavedData.get(level.getServer());store.ensure(p.getUUID(),n->0);store.update(p.getUUID(),n->0,k->{k.clearScans();return true;});var scan=ScanTargetResolver.inventory(new ItemStack(Items.STONE)).orElseThrow();var data=PhotoData.summary(scan,Items.STONE.getDescription());data.put("item",new ItemStack(Items.STONE).save(new CompoundTag()));var first=PhotoData.create(true,data);var copy=first.copy();h.assertTrue(ScanCamera.Photograph.learn(p,first)&&first.isEmpty(),"Developed photo grants real scan and consumes once");h.assertTrue(!ScanCamera.Photograph.learn(p,copy)&&copy.getCount()==1,"Already scanned photos remain intact and grant nothing");var entity=new net.minecraft.world.entity.monster.Skeleton(net.minecraft.world.entity.EntityType.SKELETON,level);var entityData=PhotoData.entity(entity);h.assertTrue(PhotoData.resolve(entityData,level).orElseThrow().kind()==PlayerKnowledge.ScanKind.ENTITY,"Entity photographs restore typed entity observations without spawning it");var invalid=new CompoundTag();invalid.putString("kind","BAD");h.assertTrue(PhotoData.resolve(invalid,level).isEmpty(),"Malformed photo data is rejected");pass(h);}
 @GameTest(template="empty") public static void workshopRestoresGeometryAndWeightedPhotographs(GameTestHelper h){var level=h.getLevel();var origin=h.absolutePos(new BlockPos(1,2,1));var piece=new PhotoWorkshopPiece(origin,net.minecraft.core.Direction.NORTH);var bounds=piece.getBoundingBox();piece.postProcess(level,level.structureManager(),level.getChunkSource().getGenerator(),level.random,bounds,new net.minecraft.world.level.ChunkPos(origin),origin);h.assertTrue(level.getBlockState(origin.offset(3,0,3)).is(Blocks.ORANGE_WOOL)&&level.getBlockState(origin.offset(3,9,3)).is(Blocks.BIRCH_SLAB),"Original orange carpet and nine-block-high roof generated");h.assertTrue(level.getBlockState(origin.offset(3,4,3)).is(Blocks.GLOWSTONE)&&level.getBlockState(origin.offset(1,4,5)).is(Blocks.OAK_STAIRS),"Second storey, staircase and central light match original layout");var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)level.getBlockEntity(origin.offset(1,1,5));chest.setItem(0,new ItemStack(Items.DIAMOND,3));piece.postProcess(level,level.structureManager(),level.getChunkSource().getGenerator(),level.random,bounds,new net.minecraft.world.level.ChunkPos(origin),origin);h.assertTrue(((net.minecraft.world.level.block.entity.ChestBlockEntity)level.getBlockEntity(origin.offset(1,1,5))).getItem(0).getCount()==3,"Repeated chunk placement cannot erase chest contents");var frames=level.getEntitiesOfClass(net.minecraft.world.entity.decoration.ItemFrame.class,new net.minecraft.world.phys.AABB(bounds.minX(),bounds.minY(),bounds.minZ(),bounds.maxX()+1,bounds.maxY()+1,bounds.maxZ()+1));h.assertTrue(frames.size()==3&&frames.stream().allMatch(f->PhotoData.valid(PhotoData.of(f.getItem()))),"Exactly three usable photos, without repeated-generation duplicates");var paintings=level.getEntitiesOfClass(net.minecraft.world.entity.decoration.Painting.class,new net.minecraft.world.phys.AABB(origin).inflate(12));h.assertTrue(paintings.size()==1&&paintings.get(0).getPos().equals(origin.offset(1,6,3))&&paintings.get(0).getDirection()==net.minecraft.core.Direction.EAST,"One painting retains its wall position and facing away from world origin");var counts=new HashMap<String,Integer>();for(int i=0;i<33;i++)counts.merge(PhotoWorkshopPiece.subject(i),1,Integer::sum);h.assertTrue(counts.size()==12&&counts.get("minecraft:zombie")==4&&counts.get("minecraft:wither_skeleton")==1&&counts.get("thaumcraft:fire_bat")==2,"All original weighted subjects retained");pass(h);}
 private static void pass(GameTestHelper h){com.mojang.logging.LogUtils.getLogger().info("WITCHINGGADGETS_TEST_PASS {}",Thread.currentThread().getStackTrace()[2].getMethodName());h.succeed();}
}
